; apx_conditional.asm -- APX conditional instructions and ZU (Phase 4a, include/iset/apx.inc)
;
; Environment
;	Assembly-time only: nothing here is executed (no APX processor is public
;	yet). fasmg assembles each instruction inside VIRTUAL and compares the
;	bytes (reference: llvm-mc 23, generated by tests/iset/_apx_diff.py; the
;	same forms pass LLVM's ccmp/ctest/cfcmov/cmov/setcc/setzucc/imulzu
;	Intel-syntax tests through tests/iset/_apx_corpus.py); a mismatch stops
;	assembly with 'encoding mismatch'. The failure cases at the end are each
;	assembled alone by _run.ps1 (-i"FAIL=n") and must stop with the quoted
;	message. By hand:  fasm2 apx_conditional.asm apx_conditional.bin
;
; What is new (EVEX map 4, spec 355828 3.1.2.3.1, 3.1.3.2)
;	- cmov<cc> ndd, r, r/m (ND=1); there is no plain {evex} cmov<cc>:
;	  ND=0 in row 4 is cfcmov's load form;
;	- cfcmov<cc>: r, m (ND=0 NF=0, reg = destination), r/m, r (NF=1, r/m =
;	  destination; also the register-register form, as llvm-mc) and
;	  ndd, r, r/m (ND=1 NF=1);
;	- set<cc> in map 4 row 4 with pp = F2 ({evex}); {zu} after the mnemonic
;	  sets ND: the upper bits of the register are zeroed;
;	- imul {zu} r, r/m, imm (69h/6Bh; {nf} too, as in Intel 817241 4.1);
;	- ccmp<scc>/ctest<scc>: cmp/test opcodes, the default flags value in
;	  P1.vvvv as [OF SF ZF CF] (not inverted), SCC in P2[3:0]; scc t/f in
;	  place of p/np; {dfv=...} with an optional comma, or a number 0-15;
;	- {evex} cmp/test encode as ccmpt/ctestt {dfv=} (as llvm-mc).
;
; FAIL 1: 'no EVEX form for this instruction'
; FAIL 2: '{nf} not supported by this instruction'
; FAIL 3: '{zu} not supported by this instruction'
; FAIL 4: '{zu} not supported by this instruction'
; FAIL 5: 'illegal instruction'
; FAIL 6: 'default flags value expected'
; FAIL 7: 'invalid default flags value'
; FAIL 8: 'invalid default flags value'
; FAIL 9: '{zu} not supported by this instruction'
; FAIL 10: 'disallowed combination of registers'
; FAIL 11: 'invalid operand size'
; FAIL 12: 'invalid combination of operands'
; FAIL 13: 'APX_F or higher required'
; FAIL 14: 'bits64 or higher required'
; FAIL 15: 'prefix not allowed with EVEX'
; FAIL 16: '{nf} not supported by this instruction'

macro expect bytes*, line&
	local n, got, k, want
	virtual at 0
		line
		n = $
		load got:n from 0
	end virtual
	virtual at 0
		db bytes
		k = $
		load want:k from 0
	end virtual
	if n <> k | got <> want
		display 'FAIL: ', `line, 13, 10
		err 'encoding mismatch'
	end if
end macro

use64
use everything

if ~ defined FAIL
	expect <48h,0Fh,42h,0C3h>, cmovb rax, rbx
	expect <62h,0F4h,0F4h,18h,42h,0C3h>, cmovb rcx, rax, rbx
	expect <62h,0F4h,0F4h,18h,42h,03h>, cmovb rcx, rax, [rbx]
	expect <62h,0ECh,7Ch,10h,45h,0CAh>, cmovne r16d, r17d, r18d
	expect <62h,0F4h,7Dh,18h,4Fh,59h,08h>, cmovg ax, bx, word [rcx+8]
	expect <62h,0F4h,0FCh,0Ch,42h,0D8h>, cfcmovb rax, rbx
	expect <62h,0F4h,0FCh,08h,42h,03h>, cfcmovb rax, [rbx]
	expect <62h,0F4h,0FCh,0Ch,42h,18h>, cfcmovb [rax], rbx
	expect <62h,0F4h,0F4h,1Ch,42h,0C3h>, cfcmovb rcx, rax, rbx
	expect <62h,0F4h,0F4h,1Ch,42h,03h>, cfcmovb rcx, rax, [rbx]
	expect <62h,0F4h,7Dh,0Ch,42h,0D8h>, cfcmovb ax, bx
	expect <62h,0ECh,0FCh,0Ch,45h,0C8h>, cfcmovnz r16, r17
	expect <62h,0ECh,78h,0Ch,4Ch,34h,6Ch>, cfcmovl [r20+r21*2], r22d
	expect <62h,0ECh,0FCh,14h,4Ah,0Ah>, cfcmovp r16, r17, [r18]
	expect <0Fh,92h,0C0h>, setb al
	expect <62h,0F4h,7Fh,08h,42h,0C0h>, {evex} setb al
	expect <62h,0F4h,7Fh,08h,42h,00h>, {evex} setb byte [rax]
	expect <62h,0F4h,7Fh,18h,42h,0C0h>, setb {zu} al
	expect <62h,0FCh,7Fh,18h,42h,0C0h>, setb {zu} r16b
	expect <62h,0F4h,7Fh,18h,42h,00h>, setb {zu} byte [rax]
	expect <62h,0F4h,7Fh,18h,40h,0C4h>, seto {zu} spl
	expect <62h,0DCh,7Fh,18h,4Fh,0C7h>, setg {zu} r31b
	expect <62h,0F4h,7Dh,18h,6Bh,0C3h,0Ah>, imul {zu} ax, bx, 10
	expect <62h,0F4h,0FCh,18h,69h,0C3h,0E8h,03h,00h,00h>, imul {zu} rax, rbx, 1000
	expect <62h,0ECh,7Dh,18h,6Bh,01h,07h>, imul {zu} r16w, [r17], 7
	expect <62h,0F4h,7Ch,1Ch,6Bh,0C3h,03h>, imul {nf} {zu} eax, ebx, 3	; Intel 817241 4.1; llvm-mc lacks it
	expect <62h,0F4h,7Ch,1Ch,6Bh,0C3h,03h>, imul {zu} {nf} eax, ebx, 3	; Intel 817241 4.1; llvm-mc lacks it
	expect <62h,0F4h,0CCh,02h,39h,0D8h>, ccmpb {dfv=of,cf} rax, rbx
	expect <62h,0F4h,84h,02h,3Bh,03h>, ccmpb {dfv=} rax, [rbx]
	expect <62h,0F4h,84h,02h,3Bh,03h>, ccmpb {dfv=}, rax, [rbx]	; optional comma (as NASM); llvm-mc does not take it
	expect <62h,0F4h,14h,0Ah,83h,0F8h,05h>, ccmpt {dfv=zf} eax, 5
	expect <62h,0F4h,24h,0Bh,80h,0F8h,05h>, ccmpf {dfv=sf} al, 5
	expect <62h,0F4h,84h,05h,81h,0F8h,78h,56h,34h,12h>, ccmpne {dfv=} rax, 12345678h
	expect <62h,0F4h,05h,0Ch,83h,38h,01h>, ccmpl {dfv=} word [rax], 1
	expect <62h,0ECh,84h,07h,39h,0C8h>, ccmpa {dfv=} r16, r17
	expect <62h,6Ch,0F8h,00h,3Bh,3Ch,0ECh>, ccmpo {dfv=of,sf,zf,cf} r31, [r20+r21*8]
	expect <62h,0F4h,4Ch,0Fh,38h,18h>, ccmpg {dfv=cf,of} byte [rax], bl
	expect <62h,0F4h,14h,04h,85h,0C9h>, ctestz {dfv=zf} ecx, ecx
	expect <62h,0F4h,84h,02h,0F7h,0C0h,01h,00h,00h,00h>, ctestb {dfv=} rax, 1
	expect <62h,0F4h,44h,0Eh,0F6h,00h,07h>, ctestle {dfv=of} byte [rax], 7
	expect <62h,0F4h,84h,05h,85h,18h>, ctestnz {dfv=} [rax], rbx
	expect <62h,0ECh,25h,08h,85h,0C8h>, ctests {dfv=sf} r16w, r17w
	expect <62h,0F4h,84h,0Ah,39h,0D8h>, {evex} cmp rax, rbx
	expect <62h,0F4h,04h,0Ah,81h,0F9h,40h,0E2h,01h,00h>, {evex} cmp ecx, 123456
	expect <62h,0F4h,04h,0Ah,84h,0DAh>, {evex} test dl, bl
	expect <62h,0D4h,84h,0Ah,0F7h,44h,80h,7Bh,40h,0E2h,01h,00h>, {evex} test qword [r8+4*rax+123], 123456
	expect <48h,39h,0D8h>, cmp rax, rbx
	expect <0A9h,01h,00h,00h,00h>, test eax, 1

else if FAIL = 1	; ND=0 NF=0 in row 4 is cfcmov's load form
	{evex} cmovb rax, rbx

else if FAIL = 2	; cmov's NF bit means cfcmov
	cmovb {nf} rax, rbx

else if FAIL = 3	; ZU: imul r, r/m, imm only
	imul {zu} rax, rbx

else if FAIL = 4	; this is the NDD form
	imul {zu} rax, rbx, rcx

else if FAIL = 5	; p/np are t/f in a source condition
	ccmpp {dfv=} rax, rbx

else if FAIL = 6
	ccmpb rax, rbx

else if FAIL = 7	; OF, SF, ZF, CF only
	ccmpb {dfv=pf} rax, rbx

else if FAIL = 8
	ccmpb 16, rax, rbx

else if FAIL = 9
	add {zu} rax, rbx

else if FAIL = 10	; no ah-bh in map 4
	setb {zu} ah

else if FAIL = 11	; cmov has no 8-bit form
	cfcmovb al, bl

else if FAIL = 12
	cfcmovb [rax], [rbx]

else if FAIL = 13
	use i386, x64
	ccmpb {dfv=} rax, rbx

else if FAIL = 14
	use32
	cfcmovb eax, ebx

else if FAIL = 15	; LOCK before EVEX: #UD
	lock ccmpb {dfv=} [rax], rbx

else if FAIL = 16
	setb {nf} al

end if